abstract:
My personal preference for cloud rendering is vanilla-esque blocky clouds, but with fancier lighting.
~~I'm also developing a 1.21.1 modpack where downgrading Iris isn't an option, and I would very much like to include these shaders.~~

Potential features:
- Edge lighting (low thickness value increases brightness value - it's not in the code I shared, but tweaking the last line of `computeClouds` gets this working)
- Sunlight/moonlight penetration and scattering (with a big gradient during sunrise/sunset)
- A second cloud layer
- Rounded corners? (Would a baked SDF texture help do this cheaply?)
- ~~No need to wait for a bugfix in Iris~~

Some of these would also benefit realistic clouds. Others might be possible using altered vanilla cloud rendering, but I'm not sure as I'm new to working on Minecraft shaders.

After two failed attempts at porting blocky clouds from other lightweight shaders, I threw together a rough proof of concept based on ILV's existing realistic clouds. I think it's promising, but it still needs work. I didn't want to take it much further without consulting, and I'd need some guidance on how to fit this into the existing configuration scheme.

<img width="2560" height="1351" alt="Image" src="https://github.com/user-attachments/assets/60c003ad-2a29-4c78-8042-51938d4adb7f" />

```glsl
#include "/utils/projections.glsl"

float sampleBlockyCloud(vec3 pos) {
    if (pos.y < CLOUD_BOTTOM_Y || pos.y > CLOUD_BOTTOM_Y + 12.0) return 0.0;
    vec2 texPos = pos.xz;
    texPos.x -= frameTimeCounter * 3;
    texPos *= 0.00025;
    return texture2D(BLOCKY_CLOUD_TEXTURE, texPos, 0).a;
}

// code past here is mostly just my notes on figuring out how computeClouds works

float sampleRealisticCloud(vec3 pos, const bool isSimplified) {
	//pos.xz = floor(pos.xz / 24.0) * 24.0;
	float cloudSample = valueNoise((pos - vec3(frameTimeCounter, 0.0, frameTimeCounter) * CLOUD_LAYER_1_SPEED * 0.8) * CLOUD_LAYER_1_SCALE) * CLOUD_LAYER_1_WEIGHT;
	pos.xz -= pos.zx * 0.2;
	cloudSample += valueNoise((pos - frameTimeCounter * CLOUD_LAYER_2_SPEED * 0.8) * CLOUD_LAYER_2_SCALE) * CLOUD_LAYER_2_WEIGHT;
	cloudSample += valueNoise((pos - frameTimeCounter * CLOUD_LAYER_3_SPEED * 0.8) * CLOUD_LAYER_3_SCALE) * CLOUD_LAYER_3_WEIGHT;
	if (!isSimplified) cloudSample += valueNoise((pos - frameTimeCounter * CLOUD_LAYER_4_SPEED * 0.8) * CLOUD_LAYER_4_SCALE) * CLOUD_LAYER_4_WEIGHT;
	float sampleWeight = (pos.y - CLOUD_BOTTOM_Y) / (CLOUD_TOP_Y - CLOUD_BOTTOM_Y) * 2.0 - 1.0;
	sampleWeight = sqrt(sqrt(1.0 - sampleWeight * sampleWeight));
	cloudSample = cloudSample / (CLOUD_LAYER_1_WEIGHT + CLOUD_LAYER_2_WEIGHT + CLOUD_LAYER_3_WEIGHT + CLOUD_LAYER_4_WEIGHT) - (1.0 - sampleWeight) * 0.5;
	const float divisor = 1.0 / ((1.0 - REALISTIC_CLOUD_DENSITY) * (1.0 - REALISTIC_CLOUD_DENSITY) + 0.01);
	return clamp((cloudSample - cloudsCoverage) * divisor, 0.0, 1.0);
}


// returns the cloud thickness and brightness (both inverted) for this pixel
vec2 computeClouds(vec3 playerPos) {

	// when the player is inside clouds, shrink the region covered by the ray march
	// this reduces the visual artifact of clouds vanishing along the horizontal eye level plane
	// TODO: this doesn't work very well for blocky clouds, since it only works if a cloud is nearby
	float playerLen = length(playerPos.xz);
	playerPos /= playerLen;
	float distLimitAmount = sampleBlockyCloud(cameraPosition + normalize(playerPos) * 20.0);
	distLimitAmount = 1.0 - pow3(1.0 - distLimitAmount);
	playerPos *= min(playerLen, mix(128 * 16.0, 20 * 16.0, distLimitAmount));

	// stepVec points in the same direction as playerPos,
	// but is scaled such that its y-component is ±1
	vec3 stepVec = playerPos;
	stepVec.xz /= abs(stepVec.y);
	stepVec.y = sign(stepVec.y);

	vec3 pos = cameraPosition;
	// find the "near" and "far" ends of the cloud layer (bottom and top if below the clouds)
	float posStartY = clamp(pos.y, CLOUD_BOTTOM_Y, CLOUD_TOP_Y);
	float posEndY = clamp(posStartY + sign(stepVec.y) * 1000.0, CLOUD_BOTTOM_Y, CLOUD_TOP_Y);
	//if (posStartY == posEndY) return vec2(1.0, 0.0); // TODO: test if this improves performance: bail if the ray is pointed away from the clouds

	// stop the raycast at foreground objects
	float maxY = abs(playerPos.y);
	posStartY = clamp(posStartY - cameraPosition.y, -maxY, maxY) + cameraPosition.y;
	posEndY = clamp(posEndY - cameraPosition.y, -maxY, maxY) + cameraPosition.y;
	if (posStartY == posEndY) return vec2(1.0, 0.0); // bail if the ray never reaches the cloud layer
	// determine the 3D start/end positions using the results of the altitude math
	pos += stepVec * abs(posStartY - pos.y);
	vec3 endPos = pos + stepVec * abs(posEndY - posStartY);
	stepVec = pos - endPos;
	stepVec /= CLOUDS_QUALITY;
	float densityMult = length(stepVec) * -0.25;
	pos = endPos;

	float dither = bayer64(gl_FragCoord.xy);
	dither = fract(dither + 1.61803398875 * mod(float(frameCounter), 3600.0));
	pos += stepVec * (dither - 0.5);

	float invThickness = 1.0;
	float invBrightness = 0.0;
	for (int i = 0; i < CLOUDS_QUALITY; i++) {
		float density = sampleBlockyCloud(pos);
		float invDensity = exp(density * densityMult);
		float sampleUp = sampleBlockyCloud(pos + cloudsShadowcasterDir);
		invThickness *= invDensity;
		invBrightness = mix(invBrightness, sampleUp, 1.0 - sqrt(invDensity));
		pos += stepVec;
	}

	return vec2(invThickness, invBrightness);
}
